export type EventName = keyof typeof SCHEMA.events;
export type Source = "client" | "web" | "server";
declare const sealed: unique symbol;
/** Only the helpers below can make one. */
export type AnalyticsEvent = { readonly name: EventName; readonly source: Source; readonly props: Readonly<Record<string, string | number | boolean>>; readonly [sealed]: true };
const make = (name: EventName, source: Source, props: Record<string, string | number | boolean | undefined>): AnalyticsEvent =>
  ({ name, source, props: Object.fromEntries(Object.entries(props).filter(([, v]) => v !== undefined)) }) as unknown as AnalyticsEvent;

